def normalize_phone(s: str) -> str:
    """Normalize a US phone number.
    If the original string contains parentheses, return the number in the
    form XXX-XXX-XXXX. Otherwise, return (XXX) XXX-XXXX.
    """
    digits = ''.join(ch for ch in s if ch.isdigit())
    if len(digits) != 10:
        raise ValueError("Phone number must contain 10 digits")
    part1, part2, part3 = digits[:3], digits[3:6], digits[6:]
    if '(' in s:
        return f"{part1}-{part2}-{part3}"
    else:
        return f"({part1}) {part2}-{part3}"

