    Consecutive capitals stay together (HTTPServer -> http_server)."""
    if not s:
        return s
    result = []
    length = len(s)
    for i, ch in enumerate(s):
        if ch.isupper():
            # Determine if underscore needed
            # Add underscore if previous is lower or digit
            if i > 0 and (s[i-1].islower() or s[i-1].isdigit()):
                result.append('_')
