def run_length_encode(s: str) -> str:
    """Compress runs of repeated characters as <char><count>. Single characters keep count 1."""
    if not s:
        return ""
    result = []
    count = 1
    prev = s[0]
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            result.append(f"{prev}{count}")
            prev = ch
            count = 1
    result.append(f"{prev}{count}")
    return "".join(result)

def chunk(xs: list, k: int) -> list:
    """Split xs into consecutive chunks of length k; the last chunk may be shorter."""
    if k <= 0:
        raise ValueError("k must be positive")
    return [xs[i:i+k] for i in range(0, len(xs), k)]

def flatten(xs: list) -> list:
    """Flatten an arbitrarily nested list of ints, preserving left-to-right order."""
    result = []
    for x in xs:
        if isinstance(x, list):
            result.extend(flatten(x))
        else:
            result.append(x)
    return result

def median(nums: list) -> float:
    """Return the median of a non-empty list of numbers.
    If the list length is odd, return the middle element.
    If even, return the mean of the two middle elements.
    The function works for any comparable numeric type.
    """
    if not nums:
        raise ValueError("median requires a non-empty list")
    sorted_nums = sorted(nums)
    n = len(sorted_nums)
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_nums[mid])
    else:
        return (sorted_nums[mid - 1] + sorted_nums[mid]) / 2.0

