    model = _load_model()
    # Assume model has a predict_proba or predict method returning a score.
    # Try common APIs.
    if hasattr(model, 'predict_proba'):
        probs = model.predict_proba([text])[0]
        # Assume positive class index 1
        score = probs[1] * 2 - 1
    elif hasattr(model, 'predict'):
