def days_between(a: str, b: str) -> int:
    """Number of days from ISO date a to ISO date b (b - a)."""
    from datetime import datetime
    fmt = "%Y-%m-%d"
    try:
        da = datetime.strptime(a, fmt).date()
        db = datetime.strptime(b, fmt).date()
    except ValueError as e:
        raise ValueError(f"Invalid ISO date format: {e}")
    return (db - da).days

def word_count(text: str) -> dict:
    """Count lowercase words (split on whitespace, strip .,!? from both ends)."""
    from collections import Counter
    # Normalize string: split on whitespace
    words = text.split()
    cleaned = []
    for w in words:
        # strip punctuation from both ends
        stripped = w.strip('.,!?')
        if stripped:
            cleaned.append(stripped.lower())
    return dict(Counter(cleaned))
